const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${paths[name]||paths[name==='domain'?'globe':'overview']}</svg>`;
const h={icon,escape,dark:true,logo:(dark,symbol)=>logo(dark,symbol)};
const logo=(dark=false,symbol=false)=>`/admin/assets/DG-Webservices-${symbol?'Icon':'Combined'}-${dark?'Dark':'Light'}-Mode-8192${!dark&&!symbol?'-1':''}.svg`;
const params=new URLSearchParams(location.search), preview=params.get('preview')==='1';
let savedTheme='dark';try{savedTheme=localStorage.getItem('dg-midnight-theme')||'dark'}catch{}
let state={concept:2,role:'client',page:'overview',phone:false,theme:params.get('theme')==='light'?'light':params.get('theme')==='dark'?'dark':savedTheme==='light'?'light':'dark'};
