const clientNav=[['overview','Overzicht','overview'],['domains','Domeinen','globe'],['hosting','Hosting','server'],['email','E-mail','mail'],['webmail','Webmail','external'],['orders','Bestellingen','layers'],['subscriptions','Abonnementen','refresh'],['invoices','Facturen','file'],['support','Support','support'],['account','Organisatie & account','settings']];
const adminNav=[['overview','Cockpit','overview'],['customers','Klanten','users'],['orders','Bestellingen','layers'],['domains','Domeinen','globe'],['hosting','Hosting','server'],['email','E-mail','mail'],['products','Producten & prijzen','grid'],['subscriptions','Abonnementen','refresh'],['invoices','Facturen & betalingen','card'],['support','Support','support'],['infrastructure','Serverdashboard','server'],['maildesk','Projectinbox','mail'],['automation','Automatisering','settings'],['communication','Communicatie','mail'],['reports','Rapportages','chart'],['settings','Instellingen & audit','shield']];
if(!fixtureParity)adminNav.push(['installations','Integraties & installatie','layers']);
const adminNavigation=()=>realDataMode?adminNav.filter(([page])=>backofficePageAllowed(page,session.actor)):adminNav;
const nav=()=>state.role==='admin'?adminNavigation():clientNav;
const route=(page='overview',concept=2,role=state.role)=>`#/${role}/${page}`;
const defaultPage=()=>realDataMode?defaultBackofficePage({actor:session.actor}):'overview';
function go(page){location.hash=route(page);}
function isDark(){return state.theme==='dark'}
function setRoute(){
 const parts=location.hash.replace(/^#\/?/,'').split('/');
 let role=defaultBackofficeRole({fixtureParity,actorRole:session.actor.role,requestedRole:params.get('role')}),page=defaultPage();
 if(parts[0]==='concept'){role=parts[2]==='admin'?'admin':'client';page=parts[3]||'overview'}
 else if(['client','admin'].includes(parts[0])){role=parts[0];page=parts[1]||'overview'}
 else if(preview&&parts[0])page=parts[0];
 if(!fixtureParity&&!isBackofficeStaffRole(session.actor.role)&&role==='admin'){role='client';page='overview';}
 if(realDataMode&&isBackofficeStaffRole(session.actor.role)&&session.actor.role!=='admin'){role='admin';if(page==='overview')page=defaultPage();}
 const allowed=(role==='admin'?adminNavigation():clientNav).map(n=>n[0]);if(role==='client')allowed.push('new');
 state.role=role;state.page=allowed.includes(page)?page:role==='admin'?defaultPage():'overview';state.concept=2;
 if(realDataMode&&isBackofficeStaffRole(session.actor.role)&&session.actor.role!=='admin'&&location.hash!==route(state.page,2,state.role))history.replaceState(null,'',route(state.page,2,state.role));
 render();
 if(preview&&window.parent!==window)window.parent.postMessage({type:'dg-midnight-route',role:state.role,page:state.page},location.origin);
 if(pendingDomain&&state.page==='new'){const form=document.getElementById('domain-search');if(form){form.querySelector('input').value=pendingDomain;pendingDomain='';form.requestSubmit()}}
}
function navLink(n){const count=n[0]==='invoices'?(commerce.openCount(state.role)):n[0]==='support'?support.count(state.role):0;return `<button class="nav-link ${state.page===n[0]?'active':''}" data-go="${n[0]}" title="${n[1]}" ${state.page===n[0]?'aria-current="page"':''}>${icon(n[2])}<span>${n[1]}</span>${count?`<span class="count">${count}</span>`:''}</button>`}
function navigation(){const groups=state.role==='client'?[['WERKRUIMTE',['overview']],['MIJN DIENSTEN',['domains','hosting','email','webmail']],['ADMINISTRATIE',['orders','subscriptions','invoices']],['PERSOONLIJK',['support','account']]]:[['WERKRUIMTE',['overview','customers']],['DIENSTEN & VERKOOP',['orders','domains','hosting','email','products']],['FINANCIËN',['subscriptions','invoices','reports']],['INFRASTRUCTUUR',['infrastructure']],['KLANTCONTACT',['maildesk','support','communication']],['OPERATIE',['automation','settings',...(!fixtureParity?['installations']:[])]]];return groups.filter(([,keys])=>!realDataMode||keys.some(k=>nav().some(n=>n[0]===k))).map(([label,keys])=>`<div class="nav-label">${label}</div><nav class="side-nav" aria-label="${label}">${keys.map(k=>nav().find(n=>n[0]===k)).filter(Boolean).map(navLink).join('')}</nav>`).join('')}
function themeSwitch(){return `<div class="theme-switch" role="group" aria-label="Kleurmodus"><button data-theme-option="light" aria-pressed="${!isDark()}" class="${!isDark()?'active':''}">${icon('sun')}<span>Light</span></button><button data-theme-option="dark" aria-pressed="${isDark()}" class="${isDark()?'active':''}">${icon('moon')}<span>Dark</span></button></div>`}
function roleSwitch(){if(realDataMode)return '';return `<div class="role-switch" role="group" aria-label="Voorbeeldomgeving"><button data-role="client" class="${state.role==='client'?'active':''}" aria-pressed="${state.role==='client'}">Klantportaal</button><button data-role="admin" class="${state.role==='admin'?'active':''}" aria-pressed="${state.role==='admin'}">DG-beheer</button></div>`}
function shell(){
 const label=(nav().find(x=>x[0]===state.page)||['','Nieuwe dienst'])[1];
 let content=modules.map(m=>m.render?.(state.role,state.page,h)).find(Boolean) || (realDataMode?renderRealEmptyPage(state.role,state.page,h):(state.role==='admin'?renderAdmin(state.page,h):state.page==='overview'?renderMidnight(h):renderPage(state.page,h)));
 return `<div class="portal-wrap"><div class="sidebar-backdrop" hidden data-ui="close-menu"></div><div class="portal"><aside class="sidebar" aria-label="Hoofdnavigatie"><div class="sidebar-brand"><a href="${route()}" aria-label="DG Webservices overzicht"><img class="brand" src="${logo(isDark())}" alt="DG Webservices"></a><button class="icon-btn sidebar-close" data-ui="close-menu" aria-label="Menu sluiten">${icon('close')}</button></div><button class="workspace-switch" data-action="organization"><span class="avatar">${state.role==='admin'?'DG':realDataMode?'KL':'DS'}</span><span><strong>${state.role==='admin'?'DG Webservices':realDataMode?escape(session.organization?.name||session.actor.organizationName||'Jouw organisatie'):'Duindorp SV'}</strong><small>${state.role==='admin'?'Beheeromgeving':'Jouw organisatie'}</small></span>${icon('down')}</button><div class="sidebar-nav-scroll">${navigation()}</div><div class="sidebar-bottom">${realDataMode?'<button type="button" class="btn quiet" data-action="real-logout">Uitloggen</button>':''}${!realDataMode||hasBackofficePermission(session.actor,'support.ticket.read')?`<button class="sidebar-help" data-go="support"><span>${icon('support')}</span><span><strong>Wij denken met je mee.</strong><small>Persoonlijke ondersteuning</small></span>${icon('arrow')}</button>`:''}${themeSwitch()}${roleSwitch()}</div></aside><div class="workspace"><header class="app-header"><button class="icon-btn mobile-menu" data-ui="menu" aria-label="Menu openen" aria-expanded="false">${icon('menu')}</button><a class="top-brand" href="${route()}"><img src="${logo(isDark())}" alt="DG Webservices"></a><div class="breadcrumbs">${state.role==='admin'?'DG-beheer':'Mijn portaal'} ${icon('chevron')} <b>${escape(label)}</b></div><button class="app-search" data-action="search">${icon('search')}<span>Zoek in je omgeving</span><kbd>⌘ K</kbd></button><div class="header-tools"><span class="demo-chip">${realDataMode?'SERVERDATA':'DEMO'}</span>${preview?'':`<button class="icon-btn preview-control" data-ui="phone" aria-label="Mobiel voorbeeld" title="Mobiel voorbeeld">${icon('mobile')}</button>`}<button class="icon-btn theme-toggle" data-ui="theme" aria-label="${isDark()?'Lightmode inschakelen':'Darkmode inschakelen'}" title="${isDark()?'Lightmode':'Darkmode'}">${icon(isDark()?'sun':'moon')}</button><button class="icon-btn notification-button" data-action="notifications" aria-label="Meldingen">${icon('bell')}<i class="notification-dot"></i></button><span class="header-line"></span><button class="organization" data-go="${state.role==='admin'?'settings':'account'}" aria-label="Accountinstellingen"><span class="avatar">${state.role==='admin'?'DG':realDataMode?'KL':'DS'}</span></button></div></header><main id="main" class="portal-main" tabindex="-1">${content}</main><footer class="portal-footer"><span>© DG Webservices <span class="footer-divider">/</span> Jouw digitale basis.</span><span>${realDataMode?'Servergegevens · externe uitvoering niet vrijgegeven':'Interactief prototype · voorbeeldgegevens'} <span class="footer-divider">/</span> <button data-action="prototype-info">${realDataMode?'Over deze omgeving':'Over dit voorbeeld'}</button></span></footer></div></div></div>`;
}
function render(){
 h.dark=isDark();document.body.className='midnight-app'+(preview?' is-preview':'');document.body.dataset.theme=state.theme;document.body.dataset.concept='2';
 document.getElementById('app').innerHTML=!preview&&state.phone?`<div class="phone-preview-toolbar"><img class="brand" src="${logo(isDark())}" alt="DG Webservices"><span>Mobiel voorbeeld</span>${themeSwitch()}${roleSwitch()}<button class="btn" data-ui="desktop">${icon('desktop')} Terug naar desktop</button></div><div class="phone-view"><div class="phone-frame"><iframe title="DG Midnight mobiel" src="/admin?preview=1&role=${state.role}&theme=${state.theme}#${state.page}"></iframe></div></div>`:shell();
 document.title=`${state.role==='admin'?'DG-beheer':'Mijn portaal'} · Midnight · DG Webservices`;
 applyTheme(false);
 modules.forEach(m=>m.decorate?.(document.getElementById('app')));
 prepareTables(document.getElementById('app'));
 const frame=document.querySelector('.phone-frame iframe');frame?.addEventListener('load',()=>frame.contentWindow?.postMessage({type:'dg-midnight-theme',theme:state.theme},location.origin));
}
function applyTheme(persist=true){
 h.dark=isDark();document.body.dataset.theme=state.theme;document.documentElement.style.colorScheme=state.theme;
 document.querySelector('meta[name="theme-color"]')?.setAttribute('content',isDark()?'#071426':'#f3f6fb');
 document.querySelectorAll('img[src*="DG-Webservices-"]').forEach(img=>{if(img.dataset.fixedTheme)return;img.src=logo(isDark(),img.getAttribute('src').includes('-Icon-'))});
 document.querySelectorAll('[data-theme-option]').forEach(b=>{const active=b.dataset.themeOption===state.theme;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});
 document.querySelectorAll('.theme-toggle').forEach(b=>{b.innerHTML=icon(isDark()?'sun':'moon');b.setAttribute('aria-label',isDark()?'Lightmode inschakelen':'Darkmode inschakelen');b.title=isDark()?'Lightmode':'Darkmode'});
 if(persist){try{localStorage.setItem('dg-midnight-theme',state.theme)}catch{}const iframe=document.querySelector('.phone-frame iframe');iframe?.contentWindow?.postMessage({type:'dg-midnight-theme',theme:state.theme},location.origin)}
}
function closeMenu(restoreFocus=false){const sidebar=document.querySelector('.sidebar'),wasOpen=sidebar?.classList.contains('mobile-open');sidebar?.classList.remove('mobile-open');sidebar?.removeAttribute('aria-modal');sidebar?.removeAttribute('role');if(restoreFocus&&wasOpen)document.querySelector('[data-ui="menu"]')?.focus();const backdrop=document.querySelector('.sidebar-backdrop');if(backdrop)backdrop.hidden=true;document.querySelector('[data-ui="menu"]')?.setAttribute('aria-expanded','false');if(!document.querySelector('.modal'))document.body.style.overflow=''}
let queuedToast=null;
function toast(message){if(!fixtureParity&&businessStore.pending){queuedToast=message;return;}if(!fixtureParity)message=String(message).replace('op dit apparaat',realDataMode?'op de server':'op de reviewserver').replace('in deze browser',realDataMode?'op de server':'op de reviewserver');clearTimeout(toastTimer);const el=document.getElementById('toast');el.className='toast';el.textContent=message;toastTimer=setTimeout(()=>{el.className='';el.textContent=''},4300)}
function closeModal(){const root=document.getElementById('modal-root');root.innerHTML='';document.getElementById('app').inert=false;document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus();returnFocus=null;modalState={};modalDirty=false;if(pendingStoreRefresh){pendingStoreRefresh=false;initializeModules();render()}}
function requestClose(){const supportForm=document.querySelector('.modal form[data-support-draft]');if(supportForm){if(!fixtureParity){support.beforeClose().then(ok=>{if(ok&&supportForm.isConnected)closeModal();}).catch(showRequestError);return;}closeModal();return}if(!modalDirty){closeModal();return}const body=document.querySelector('.modal-body');if(!body||body.querySelector('.modal-unsaved'))return;const prompt=document.createElement('div');prompt.className='modal-unsaved notice';prompt.setAttribute('role','alert');prompt.innerHTML=`<strong>Je hebt nog niet opgeslagen wijzigingen.</strong><div class="modal-actions"><button class="btn" data-action="keep-editing">Verder bewerken</button><button class="btn primary" data-action="discard-modal">Wijzigingen verwerpen</button></div>`;body.prepend(prompt);prompt.scrollIntoView({block:'nearest'});prompt.querySelector('button')?.focus()}
function prepareTables(root){root?.querySelectorAll('table').forEach(table=>{const heads=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());table.setAttribute('role','table');table.querySelectorAll('thead,tbody').forEach(g=>g.setAttribute('role','rowgroup'));table.querySelectorAll('tr').forEach(row=>row.setAttribute('role','row'));table.querySelectorAll('thead th').forEach(th=>{th.setAttribute('scope','col');th.setAttribute('role','columnheader')});table.querySelectorAll('tbody tr').forEach(row=>[...row.cells].forEach((td,n)=>{td.dataset.label=heads[n]||'';td.setAttribute('role','cell')}))});}
function modal(title,body,options={}){
 const existed=Boolean(document.querySelector('.modal'));if(!existed)returnFocus=document.activeElement;
 const size=['wide','small'].includes(options.size)?options.size:'standard';
 document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><section class="modal modal--${size}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><span class="eyebrow">DG WEBSERVICES</span><h2 id="modal-title" tabindex="-1">${escape(title)}</h2></div><button class="icon-btn" data-action="close" aria-label="Venster sluiten">${icon('close')}</button></header><div class="modal-body">${body}</div></section></div>`;
 document.getElementById('app').inert=true;document.body.style.overflow='hidden';modalDirty=false;prepareTables(document.getElementById('modal-root'));setTimeout(()=>document.getElementById('modal-title')?.focus(),0);
}
const note='<div class="modal-note">Interactieve demo · wijzigingen worden lokaal op dit apparaat bewaard. Er worden geen echte diensten aangepast, berichten verstuurd of betalingen uitgevoerd.</div>';
const actions=(label,action='save',extra='')=>`<div class="modal-actions"><button class="btn" data-action="close">Sluiten</button><button class="btn primary" data-action="${action}" ${extra}>${label} ${icon('arrow')}</button></div>`;
