document.addEventListener('keydown',e=>{
 if(e.key==='Enter'&&e.target.closest('.d4-domain-form')&&e.target.matches('input')){e.preventDefault();pendingDomain=e.target.value;go('new')}
 if(e.key==='Escape'){if(document.querySelector('.modal'))requestClose();else closeMenu(true)}
 if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();action('search')}
 if(e.key==='Tab'&&!document.querySelector('.modal')&&document.querySelector('.sidebar.mobile-open')){const nodes=[...document.querySelectorAll('.sidebar.mobile-open button,.sidebar.mobile-open a[href]')].filter(x=>!x.disabled&&!x.hidden&&x.type!=='hidden'&&!x.closest('[hidden]')&&x.getAttribute('tabindex')!=='-1');if(nodes.length){const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||!nodes.includes(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!nodes.includes(document.activeElement))){e.preventDefault();first.focus()}}}
 if(e.key==='Tab'&&document.querySelector('.modal')){const nodes=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea,.modal a[href]')].filter(x=>!x.disabled&&!x.hidden&&x.type!=='hidden'&&!x.closest('[hidden]')&&x.getAttribute('tabindex')!=='-1');if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||!nodes.includes(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!nodes.includes(document.activeElement))){e.preventDefault();first.focus()}}
});
function downloadCSV(kind){const body='Demonstratiegegevens DG Webservices\nOnderdeel;Klant;Omschrijving;Bedrag EUR\n'+escape(kind)+';Duindorp SV;Hosting en mail oktober;19.95\n'+escape(kind)+';Studio Noord;Hosting Zakelijk;9.95\n'+escape(kind)+';Bakkerij West;Hosting Start;4.95\n';const blob=new Blob(['\uFEFF'+body],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='DG-'+kind+'-demogegevens.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('CSV met demogegevens gedownload.')}
